import {setupMotion, transitionPage} from './motion.js';
const [assets,menu,brand,layouts]=await Promise.all(['assets.json','menu.json','brand-assets.json','menu-layout.json'].map(url=>fetch(url).then(r=>r.json())));
const A=(key,group='homeDesign')=>assets[group]?.[key]||'';
const first=g=>Object.values(assets[g]||{})[0];
const photo=(src,alt,cls='')=>`<img class="${cls}" src="${src}" alt="${alt}" decoding="async">`;
const svg=(src,alt='',rotate=false)=>`<span class="svg-fit" ${rotate?'data-rotate="true"':''}><img src="${src}" alt="${alt}"></span>`;
const linkButton=(text,href,cls='')=>`<a class="button ${cls}" href="${href}">${text}</a>`;
const wa=text=>`https://wa.me/56933864284?text=${encodeURIComponent(text)}`;
const money=n=>new Intl.NumberFormat('es-CL',{style:'currency',currency:'CLP',maximumFractionDigits:0}).format(n);
let selectedSize='M',cart=[];
try{const saved=JSON.parse(localStorage.getItem('ilfuogo-cart')||'[]');if(Array.isArray(saved))cart=saved.filter(x=>['S','M','L','XL'].includes(x.size)&&Number.isInteger(x.qty)&&x.qty>0&&x.qty<=20)}catch{}
const saveCart=()=>{try{localStorage.setItem('ilfuogo-cart',JSON.stringify(cart))}catch{}};
const navItems=[['INICIO','#/','home'],['MENÚ','#/carta/compartir','menu'],['LA TIENDA','#/tienda','shop']];
function shell(page){document.body.className=page;document.querySelector('#header').innerHTML=`<a class="brand" href="#/" aria-label="Il Fuogo, inicio">${photo('assets/logo.svg','Il Fuogo')}</a><button class="mobile-toggle" aria-label="Abrir menú" aria-expanded="false">☰</button><nav class="nav" aria-label="Navegación principal">${navItems.map(([t,h,p])=>`<a href="${h}" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}>${t}</a>`).join('')}${linkButton(page==='home'?'VEN A CONOCERNOS':'VISÍTANOS','#/contacto')}${page==='shop'?`<button class="cart-launch">Carrito (${cart.reduce((n,x)=>n+x.qty,0)})</button>`:''}</nav>`;
 document.querySelector('#footer').innerHTML=`<div class="footer-brand">${photo(A('imgTexto'),'Il Fuogo')}<p>MADE IN CHILE · MOOD ITALIANO</p></div><div class="footer-location"><strong>ESTACIÓN 140</strong><p>Puerto Varas · Chile</p><small>LUN - SÁB &nbsp;12:30 - 22:00<br>DOM &nbsp;12:30 - 17:30</small></div><div class="footer-links"><nav><a href="#/">INICIO</a><a href="#/carta/compartir">MENÚ</a><a href="#/contacto">CONTACTO</a></nav><a class="instagram" href="https://www.instagram.com/ilfuogo.pv/" target="_blank" rel="noopener">${photo(A('imgLayer1'),'Instagram')}ilfuogo.pv</a><small>© 2026 IL FUOGO</small></div>`;
 document.querySelector('.mobile-toggle').onclick=e=>{const open=document.querySelector('.nav').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open));e.currentTarget.setAttribute('aria-label',open?'Cerrar menú':'Abrir menú')};document.querySelector('.cart-launch')?.addEventListener('click',openCart);
}
function dish(key,label,route){return `<a class="dish-photo" href="${route}">${photo(A(key),label)}<span class="dish-label">${label}${photo(A('imgArrow6'),'')}</span></a>`}
function home(){shell('home');return `<section class="hero"><div class="hero-copy"><h1 class="hero-heading">${traced('ENTRE_ITALIA_Y_PATAGONIA','Entre Italia y Patagonia, alma del chef')}</h1><div class="hero-meta"><span>MADE IN <b>CHILE</b></span><span>MOOD <b>ITALIANO</b></span></div>${photo(A('imgRectangle'),'','hero-note')}${photo(A('imgRectangle1'),'','hero-signature')}<div class="hero-meta"><span>PUERTO <b>VARAS</b></span><span><b>ESTACIÓN<br>140</b></span></div></div>${photo(A('img41'),'Fachada de Il Fuogo en Puerto Varas','hero-photo')}</section><section class="carta" id="carta">${photo(A('imgAranciniO7A77741'),'Arancini preparados en Il Fuogo','carta-bg')}<div class="carta-shade"></div><div class="carta-content"><h2 class="display">LA<br>CARTA</h2><p>Cocina ítalo-patagónica de producto fresco, sabores honestos y preparaciones para compartir. Una carta que acompaña cada momento.</p>${linkButton('RESERVA TU MESA ↗','#/contacto','reserve-hero')}<div class="category-links">${[['compartir','Para compartir','imgGroup5'],['fondos','Fondos','imgGroup4'],['postres','Para terminar','imgGroup6'],['bebidas','Para beber','imgGroup7']].map(([r,t,k])=>`<a class="category-link" href="#/carta/${r}" aria-label="${t}">${photo(A('imgEllipse1'),'','circle')}${svg(A(k),t)}</a>`).join('')}</div></div></section><section class="featured" aria-label="Nuestra cocina"><div class="feature-grid">${dish('imgFotoIlFuogoArancini','ARANCINI DE OSOBUCO Y MOZZARELLA','#/carta/compartir')}${dish('imgFotoIlFuogoPizza3','PIZZA LA CAMARÓN','#/carta/fondos')}</div><div class="daily"><div class="daily-copy"><p class="eyebrow">LUN — VIE / EXCEPTO FESTIVOS</p><div><h2 class="display">MENÚ DEL<span>DÍA</span></h2><strong class="display">$12.990</strong></div><p>13:00 — 16:00 HRS</p></div>${dish('imgO7A77291','FETTUCCINI AL RAGÚ','#/carta/fondos')}</div><h2 class="sabor">${traced('SIN_ATAJOS_NI_EXCUSAS','Sin atajos ni excusas, solo sabor')}</h2><div class="three-dishes">${dish('imgO7A77501','SANDWICH EL CRIOLLO','#/carta/fondos')}${dish('imgO7A76831','SPAGHETTI CARBONARA','#/carta/fondos')}${dish('imgO7A78001',"SPAGHETTI ALL’AMATRICIANA",'#/carta/fondos')}</div></section><section class="promos"><div class="promos-heading"><h2 class="display">LAS PROMOS DEL MES</h2><p>Sujeto a consumo de alimentos<strong>Desde las 17.00 hrs</strong></p></div><div class="promo-grid">${[
 ['Martes','HAPPY<br>DAY','$3.000','imgHf20260728195911D1421A2CB4Ae49Db9A95D6Fe9748Bd7A1','Aperol, Ramazzotti, Piscola y Fernet'],['Miércoles','','SCHOP<br>$3.000','img9C752C4C974D48Bf8A97F16Ef19F0666202610081',''],['Jueves','AFTER<br>OFFICE','SANGRÍA<br>2X1','img0F480A14Bb8A42E5907E5C97F6Ab6931202610081',''],['Viernes','HAPPY<br>DAY','$3.000','imgHf20260728195911D1421A2CB4Ae49Db9A95D6Fe9748Bd7A1','Aperol, Ramazzotti, Piscola y Fernet'],['Sábado','','PISCO SOUR<br>$1.500','imgHf20260728234258F313Bb897Fbc471FAc8C68A147Cc28D21','Máximo 3 por persona'],['Domingo','','DE VINO Y<br>PASTA','imgF6223E16Be0143F9B97FC16Df1C22B72202610081','']].map(([day,title,offer,img,note])=>`<article class="promo-card">${photo(A(img),`Promoción de ${day}`)}<p class="script day">${day}</p><h3 class="display">${title}</h3><p class="display offer">${offer}</p>${note?`<small>${note}</small>`:''}</article>`).join('')}</div></section><section class="merch"><div class="merch-copy"><p class="eyebrow">02 / LA COCINA TAMBIÉN SE LLEVA</p><h2><span class="script">Lleva el</span><br><span class="display">FUEGO<br>CONTIGO</span></h2><p>Poleras y polerones de Il Fuogo.</p>${linkButton('VER MERCH','#/tienda','dark')}</div>${photo(A('imgBenditoMockupMbFreeTShirt4'),'Polera blanca Il Fuogo')}${photo(A('imgChefEnCocinaComercialConUniformeDeMarca1'),'Chef con la polera Il Fuogo')}</section>`}
function contact(){shell('contact');return `<section class="contact-hero"><div class="contact-hero-copy"><p class="eyebrow">03 / DÓNDE ENCONTRARNOS</p><h1>${traced('UNA_MESA_QUE','Una mesa que deja recuerdos')}</h1></div>${photo(A('imgFotoIlFuogoPizza','contactHero'),'Pizza de Il Fuogo')}</section><div class="venue-gallery">${photo(first('bar'),'Barra de Il Fuogo')}${photo(first('shelf'),'Detalle del bar')}${photo(first('room'),'Mesas y mural del restaurante')}</div><section class="contact-grid"><div class="location"><p class="eyebrow">VISÍTANOS / PUERTO VARAS</p><h1 class="display">ESTACIÓN<strong>140</strong></h1><p class="city">Puerto Varas, Chile</p><a class="map" style="display:block" href="https://www.google.com/maps/search/?api=1&query=Il+Fuogo+Estaci%C3%B3n+140+Puerto+Varas" target="_blank" rel="noopener" aria-label="Ver ubicación en Google Maps">${photo(A('imgCapturaDePantalla20261019ALaS115154AM1','location'),'Mapa referencial de Puerto Varas')}<span class="map-label"><i></i>IL FUOGO</span></a><p class="eyebrow">HORARIOS</p><p class="hours"><b>LUN - SÁB</b> &nbsp;12:30 — 22:00<br><b>DOMINGO</b> &nbsp;12:30 — 17:30</p>${linkButton('CÓMO LLEGAR ↗','https://www.google.com/maps/search/?api=1&query=Il+Fuogo+Estaci%C3%B3n+140+Puerto+Varas')}</div><div class="reservation"><h2 class="display">RESERVA<span>TU MESA</span></h2><form id="reservation"><label>NOMBRE<input name="nombre" placeholder="Tu nombre" autocomplete="name" maxlength="100" required></label><label>CORREO<input name="correo" type="email" placeholder="Tu correo electrónico" autocomplete="email" maxlength="150" required></label><div class="form-row"><label>FECHA<input name="fecha" type="date" required></label><label>HORA<select name="hora" required aria-label="Hora de reserva"><option value="">Selecciona hora</option></select></label></div><label>PERSONAS<select name="personas" required><option value="">¿Cuántos serán?</option>${Array.from({length:12},(_,i)=>`<option value="${i+1}">${i+1} ${i?'personas':'persona'}</option>`).join('')}<option value="Más de 12">Más de 12 personas</option></select></label><button class="button" type="submit">RESERVAR POR WHATSAPP ↗</button><p class="form-note">Abriremos WhatsApp con los datos de tu reserva. Pulsa «Enviar» para solicitarla; queda sujeta a confirmación del restaurante.</p><p id="reservation-status" role="status" class="form-note"></p></form></div></section>`}
function shop(){shell('shop');return `<section class="shop"><div class="shop-hero"><div><p class="eyebrow">MERCH IL FUOGO</p><h1><span class="script">Lleva el</span><br><span class="display">FUEGO<br>CONTIGO</span></h1><p>Poleras y polerones Il Fuogo.<br>La cocina también se lleva. Identidad para llevar, dentro y fuera de la cocina.</p></div>${photo(A('imgBenditoMockupNFreeTShirt3','tienda'),'Polera Il Fuogo: Donde el fuego transforma')}</div><div class="shop-gallery">${photo(A('imgBenditoMockupFreeTShirt013','tienda'),'Polera Il Fuogo negra, vista frontal')}${photo(A('imgBenditoMockupCccFreeTShirt013','tienda'),'Polera Il Fuogo: Alma del chef')}${photo(A('imgChefEnCocinaComercialConUniformeDeMarca1','tienda'),'Polera Il Fuogo en la cocina')}</div><div class="product-row"><div class="product-box"><div><h2>Polera Il Fuogo</h2><div class="price">$15.990</div><fieldset class="sizes"><legend>Selecciona tu talla</legend>${['S','M','L','XL'].map(s=>`<button type="button" class="size" data-size="${s}" aria-pressed="${selectedSize===s}">${s}</button>`).join('')}</fieldset><small>COCINA · IDENTIDAD · TERRITORIO</small><button class="button" id="add-cart">AGREGAR AL CARRITO</button></div><p><b>Polera Il Fuogo en serigrafía a dos colores y diseñada en Puerto Varas.</b> Una prenda que lleva nuestra identidad, inspiración ítalo-patagónica y alma de barrio a todas partes.</p></div>${photo(A('imgBenditoMockupMbFreeTShirt2','tienda'),'Detalle de la polera Il Fuogo')}</div></section>`}
const titles={compartir:['Todo comienza','EN LA MESA'],fondos:['Cada plato','CUENTA UNA HISTORIA'],postres:['Sin atajos ni excusas','SOLO SABOR'],bebidas:['Donde hay fuego','TAMBIÉN HAY UNA COPA']};
const categories=[['compartir','Para compartir'],['fondos','Fondos'],['postres','Para terminar'],['bebidas','Para beber']];
const section=(key,label)=>`<section class="menu-section section-${key}"><h2>${label}</h2><div class="menu-items">${(menu[key]||[]).map(x=>`<article class="menu-item"><div><h3>${x.name}</h3><p>${x.description}</p></div><span class="menu-price">[${x.price}]</span></article>`).join('')}</div></section>`;
function mobileMenuPage(category){shell('menu');if(!titles[category])category='compartir';const [script,bold]=titles[category];return `<nav class="menu-tabs" aria-label="Categorías de la carta">${categories.map(([k,t])=>`<a href="#/carta/${k}" class="${k===category?'active':''}" ${k===category?'aria-current="page"':''}>${t}</a>`).join('')}</nav><div class="menu-page menu-${category}"><h1 class="menu-title">${category!=='bebidas'&&category!=='postres'?traced({compartir:'TODO_COMIENZA_EN_LA_MESA',fondos:'CADA_PLATO'}[category],script+' '+bold):`<span class="script">${script}</span><br><span class="display">${bold}</span>`}</h1>${category==='compartir'?section('compartir','PARA COMPARTIR · ENTRADAS')+section('ensaladas','ENSALADAS Y CREMA DEL DÍA')+`<section class="menu-section"><h2>PARA TODOS</h2><article class="menu-item"><div><h3>PALITOS DE AJO</h3><p>Pomodoro · Salsa brava · Pesto</p></div><span class="menu-price">[7.000]<br>[7.000]<br>[8.000]</span></article><article class="menu-item"><div><h3>MENÚ INFANTIL</h3><p>Pizzetta margarita o pepperoni, milanesitas de pollo o spaghetti Alfredo.</p></div><span class="menu-price">[7.900]</span></article></section>`:''}${category==='fondos'?section('fondos','FONDOS')+`<section class="menu-section"><h2 class="menu-title"><span class="script">Donde el fuego</span><br><span class="display">TRANSFORMA</span></h2></section>`+section('pizzas','PIZZAS'):''}${category==='postres'?section('postres','PARA TERMINAR'):''}${category==='bebidas'?drinks():''}<a class="menu-next" href="#/carta/${categories[(categories.findIndex(x=>x[0]===category)+1)%4][0]}">${categories[(categories.findIndex(x=>x[0]===category)+1)%4][1].toUpperCase()} →</a></div>`}
function drinks(){return `<div class="drink-columns menu-section">${(menu.drinks||[]).map(block=>`<section class="drink-block"><h2>${block.title}</h2>${block.items.map(x=>`<div class="drink-row"><strong>${x.name}${x.price?' <span style="float:right;font-weight:400">['+x.price+']</span>':''}</strong>${x.description||''}</div>`).join('')}</section>`).join('')}</div>`}

const traced=(name,alt)=>{const a=brand['TEXTO TRAZADO/'+name+'.svg'];return `<span class="traced" style="aspect-ratio:${a.w}/${a.h}">${svg(a.src,alt)}</span>`};
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function menuPage(category){
 if(!layouts[category])category='compartir';
 const mobile=mobileMenuPage(category),layout=layouts[category];
 const layers=layout.items.map(a=>{const pos=`left:${a.x}px;top:${a.y}px;width:${a.w}px;height:${a.h}px;`;
 if(a.type==='text')return `<p class="design-text" data-figma-node="${a.id}" style="${pos}font-size:${a.size}px;font-weight:${a.weight};${a.italic?'font-style:italic;':''}">${escapeHTML(a.text)}</p>`;
 if(a.type==='next')return `<a class="design-next" href="${a.href}" style="${pos}" aria-label="${a.label}"><strong>${a.label}</strong>${photo(a.src,'')}<span aria-hidden="true">→</span></a>`;
 if(a.type==='photo')return `<img class="design-photo" src="${a.src}" alt="" style="${pos}z-index:${a.layer}">`;
 return `<span class="design-art" style="${pos}z-index:${a.layer}"><img src="${a.src}" alt="${escapeHTML(a.alt||'')}" style="transform:scale(${a.w/a.naturalW});transform-origin:0 0"></span>`;
 }).join('');
 return `<div class="design-canvas-wrap" data-height="${layout.height}"><div class="design-canvas" style="height:${layout.height}px">${layers}</div></div><div class="mobile-menu">${mobile}</div>`;
}
let canvasObserver;
function fitCanvases(){canvasObserver?.disconnect();canvasObserver=new ResizeObserver(entries=>{for(const e of entries){const scale=e.target.clientWidth/1440;e.target.style.height=Number(e.target.dataset.height)*scale+'px';e.target.firstElementChild.style.transform=`scale(${scale})`}});document.querySelectorAll('.design-canvas-wrap').forEach(el=>canvasObserver.observe(el));}

let observer;function fitSvgs(){observer?.disconnect();observer=new ResizeObserver(es=>es.forEach(e=>fit(e.target)));function fit(w){const im=w.querySelector('img');if(!im?.naturalWidth)return;const rot=w.hasAttribute('data-rotate'),iw=im.naturalWidth,ih=im.naturalHeight,scale=Math.min(w.clientWidth/(rot?ih:iw),w.clientHeight/(rot?iw:ih));im.style.transform=rot?`scale(${scale}) translateX(${ih}px) rotate(90deg)`:`scale(${scale})`;};document.querySelectorAll('.svg-fit').forEach(w=>{observer.observe(w);const im=w.querySelector('img');im.addEventListener('load',()=>fit(w),{once:true});fit(w)})}
function setupReservation(){const f=document.querySelector('#reservation');if(!f)return;const date=f.elements.fecha,hour=f.elements.hora;const today=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Santiago',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());date.min=today;function times(){const old=hour.value;const sunday=date.value&&new Date(date.value+'T12:00:00').getDay()===0;const end=sunday?17*60:21*60+30;hour.innerHTML='<option value="">Selecciona hora</option>';for(let n=12*60+30;n<=end;n+=30){const v=String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');hour.add(new Option(v,v))}if([...hour.options].some(o=>o.value===old))hour.value=old}date.addEventListener('change',times);times();f.addEventListener('submit',e=>{e.preventDefault();if(!f.reportValidity())return;if(date.value<today){date.setCustomValidity('Selecciona una fecha desde hoy.');date.reportValidity();return}date.setCustomValidity('');const d=new FormData(f),formatted=new Intl.DateTimeFormat('es-CL',{dateStyle:'long'}).format(new Date(d.get('fecha')+'T12:00:00'));const message=`Hola Il Fuogo, quisiera solicitar una reserva.\n\nNombre: ${d.get('nombre').trim()}\nCorreo: ${d.get('correo').trim()}\nFecha: ${formatted}\nHora: ${d.get('hora')}\nPersonas: ${d.get('personas')}\n\nQuedo atento/a a su confirmación. ¡Gracias!`;window.open(wa(message),'_blank','noopener');document.querySelector('#reservation-status').textContent='Mensaje preparado. Envíalo en WhatsApp para solicitar la reserva.'});date.addEventListener('input',()=>date.setCustomValidity(''))}
function openCart(){const d=document.querySelector('#cart');document.querySelector('#cart-content').innerHTML=cart.length?`${cart.map((x,i)=>`<div class="cart-line"><div><b>Polera Il Fuogo · ${x.size}</b><br>${x.qty} × ${money(15990)}</div><button data-remove="${i}" aria-label="Quitar polera talla ${x.size}">Quitar</button></div>`).join('')}<p class="cart-total">Total: ${money(cart.reduce((s,x)=>s+x.qty*15990,0))}</p><a class="button" href="${wa('Hola Il Fuogo, quisiera pedir:\n'+cart.map(x=>`${x.qty} × Polera Il Fuogo, talla ${x.size}, ${money(15990)} c/u`).join('\n')+'\nTotal: '+money(cart.reduce((s,x)=>s+x.qty*15990,0))+'\n¿Me confirman disponibilidad y cómo coordinar el pago y la entrega?')}" target="_blank" rel="noopener">PEDIR POR WHATSAPP ↗</a><p class="cart-note">Confirma disponibilidad, pago y entrega con Il Fuogo por WhatsApp. Este carrito no realiza cobros.</p>`:'<p class="empty">Tu carrito está vacío. Elige una talla y agrega tu polera.</p>';document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{cart.splice(Number(b.dataset.remove),1);saveCart();openCart();shell('shop')});if(!d.open)d.showModal()}
document.querySelector('#cart .close').onclick=()=>document.querySelector('#cart').close();document.querySelector('#cart').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close()}});
function render(){const path=(location.hash.slice(1)||'/').split('/').filter(Boolean);const main=document.querySelector('#main');if(path[0]==='contacto'){main.innerHTML=contact();document.title='Reserva tu mesa — Il Fuogo'}else if(path[0]==='tienda'){main.innerHTML=shop();document.title='La tienda — Il Fuogo'}else if(path[0]==='carta'){main.innerHTML=menuPage(path[1]);document.title='La carta — Il Fuogo'}else{main.innerHTML=home();document.title='Il Fuogo — Cocina ítalo-patagónica'}fitSvgs();fitCanvases();setupReservation();document.querySelectorAll('.size').forEach(b=>b.onclick=()=>{selectedSize=b.dataset.size;document.querySelectorAll('.size').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))});document.querySelector('#add-cart')?.addEventListener('click',()=>{const x=cart.find(x=>x.size===selectedSize);if(x)x.qty=Math.min(20,x.qty+1);else cart.push({size:selectedSize,qty:1});saveCart();shell('shop');openCart()});window.scrollTo({top:0,left:0,behavior:'instant'});setupMotion(main)}
window.addEventListener('hashchange',()=>transitionPage(render));render();
